import{_ as l,o as e,c as i,at as a}from"./chunks/framework.CY22Hent.js";const n="/assets/ai_202603121648.DR1HNEjq.jpeg",d="/assets/ai_2026-03-12_173644_491.B2LKBg4W.png",o="/assets/ai_2026-03-12_175549_395.BxAUNy1L.png",A="/assets/ai_2026-03-24_162605_454.DOlzW2GP.png",h=JSON.parse('{"title":"AI Agent笔记","description":"","frontmatter":{"title":"AI Agent笔记","date":"2026-03-12T00:00:00.000Z","lastUpdated":"2026-03-12T00:00:00.000Z","categories":["AI"],"tags":["AI","AI Agent"]},"headers":[],"relativePath":"blogs/AI/AIAgent笔记.md","filePath":"blogs/AI/AIAgent笔记.md"}'),r={name:"blogs/AI/AIAgent笔记.md"};function g(p,t,s,_,u,c){return e(),i("div",null,[...t[0]||(t[0]=[a('<p>[toc]</p><h1 id="ai-agent笔记" tabindex="-1">AI Agent笔记 <a class="header-anchor" href="#ai-agent笔记" aria-label="Permalink to &quot;AI Agent笔记&quot;">​</a></h1><p><img src="'+n+'" alt="ai_202603121648.jpeg" loading="lazy"></p><h2 id="ai-agent-介绍" tabindex="-1">AI Agent 介绍 <a class="header-anchor" href="#ai-agent-介绍" aria-label="Permalink to &quot;AI Agent 介绍&quot;">​</a></h2><p>AI Agent（人工智能代理） 是一个能够感知环境、进行决策并执行行动，以达成特定目标的智能软件实体，它不仅仅是回答问题的聊天机器人，更是能够动手做事的智能执行者。</p><blockquote><p>什么是 Agent？</p></blockquote><p>AI Agent（人工智能代理）本质是自动执行任务的程序，核心在于让模型不只回答问题，而是按步骤完成动作。</p><p><span style="color:red;">AI Agent = LLM (大脑，大语言模型) + Planning (规划) + Tool use (工具使用) + Memory (记忆)。</span></p><ul><li>LLM (大脑，大语言模型)： 作为核心推理机，负责理解意图、生成文本和进行逻辑判断。</li><li>Planning (规划)： 能够将复杂的目标（如&quot;帮我解题&quot;）拆解成可执行的步骤。</li><li>Memory (记忆)： 记录对话历史（短期）和存储专业知识库（长期）。</li><li>Tool Use (工具使用)： 能够根据需求去查谷歌搜索、读数据库、甚至跑 Python 代码。</li></ul><p><img src="'+d+'" alt="ai_2026-03-12_173644_491.png" loading="lazy"></p><blockquote><p>传统程序和 AI Agent 的区别</p></blockquote><p>传统的软件程序遵循固定的指令流程：输入 → 处理 → 输出。</p><p>而AI Agent 则更像一个有自主性的员工，它能够：</p><ul><li>理解任务目标：明白你想要什么结果</li><li>制定计划：思考如何达成目标</li><li>使用工具：调用各种资源和 API 执行任务</li><li>自我调整：根据反馈优化策略</li><li>持续执行：直到完成任务或遇到无法解决的问题</li></ul><blockquote><p>传统AI模型和AI Agent的区别</p></blockquote><p>AI Agent 本身是在传统AI模型的基础上，加入了规划、记忆和工具使用等功能，使得它能够更智能、更灵活地完成任务。</p><table tabindex="0"><thead><tr><th>维度</th><th>传统 AI 模型</th><th>AI Agent</th></tr></thead><tbody><tr><td>交互方式</td><td>单次输入输出</td><td>多轮对话、持续交互</td></tr><tr><td>决策能力</td><td>基于输入直接推理</td><td>规划、反思、迭代优化</td></tr><tr><td>工具使用</td><td>无法主动调用外部工具</td><td>可调用搜索、计算器、API 等</td></tr><tr><td>记忆机制</td><td>仅限当前上下文</td><td>短期+长期记忆</td></tr><tr><td>目标导向</td><td>完成单一预测任务</td><td>完成复杂目标</td></tr><tr><td>错误处理</td><td>输出即结束</td><td>可自我纠错、重试</td></tr></tbody></table><blockquote><p>AI Agent 的发展历程</p></blockquote><p><img src="'+o+'" alt="ai_2026-03-12_175549_395.png" loading="lazy"></p><p>阶段一：概念萌芽期（1950s-2010s）</p><ul><li>1950s：图灵测试提出，Agent 概念初现</li><li>1990s：多智能体系统研究兴起</li><li>2000s：规则驱动的聊天机器人（如 ELIZA）</li><li>特点：基于规则，能力有限</li></ul><p>阶段二：深度学习赋能期（2010s-2020）</p><ul><li>2012：深度学习在 ImageNet 取得突破</li><li>2017：Transformer 架构问世</li><li>2018-2020：BERT、GPT 系列模型发布</li><li>特点：理解能力提升，但仍是&quot;被动工具&quot;</li></ul><p>阶段三：大模型 Agent 爆发期（2021-至今）</p><ul><li>2022.11：ChatGPT 发布，展现强大对话能力</li><li>2023.03：GPT-4 + Plugins，首次实现工具调用</li><li>2023.03：AutoGPT 开源，自主 Agent 概念验证</li><li>2023.05：LangChain、LlamaIndex 等框架成熟</li><li>2024-2025：企业级 Agent 应用大规模落地</li><li>特点：真正的自主性、工具使用、任务规划</li></ul><blockquote><p>AI Agent 的主要类型与应用场景</p></blockquote><p>根据复杂度和自主性，AI Agent 可以分为不同类型，应用于各种场景。</p><table tabindex="0"><thead><tr><th>类型</th><th>特点</th><th>应用场景举例</th></tr></thead><tbody><tr><td>单一任务 Agent</td><td>专注于完成一件特定事情，功能专一。</td><td>智能客服机器人、自动数据录入助手、个人日程提醒助手。</td></tr><tr><td>多模态 Agent</td><td>能理解和处理文本、图像、语音等多种信息。</td><td>根据草图生成网站代码、分析医学影像并生成报告、视频内容自动摘要。</td></tr><tr><td>自主 Agent</td><td>拥有较高自主性，可长期运行并主动管理复杂目标。</td><td>自动驾驶汽车、自动化股票交易系统、智能游戏 NPC（非玩家角色）。</td></tr><tr><td>模拟 Agent</td><td>在虚拟环境中进行模拟、测试和训练。</td><td>训练机器人完成抓取任务、模拟城市交通流量优化、新药研发的分子模拟。</td></tr></tbody></table><h2 id="ai-agent-的工作原理" tabindex="-1">AI Agent 的工作原理 <a class="header-anchor" href="#ai-agent-的工作原理" aria-label="Permalink to &quot;AI Agent 的工作原理&quot;">​</a></h2><p>一个典型的 AI Agent 由三个关键部分协同工作。</p><p><span style="color:red;">AI Agent = LLM (大脑，大语言模型) + Planning (规划) + Tool use (工具使用) + Memory (记忆)。</span></p><ul><li>LLM (大脑，大语言模型)：是Agent 的决策中心和推理引擎。 <ul><li>理解用户输入的目标和上下文，分析当前状况，然后决定下一步该做什么，它负责规划和分解复杂任务。</li><li>就像公司的 CEO 或指挥官，负责战略思考、任务规划和下达指令。</li></ul></li><li>Planning (规划)：是Agent 的手和脚，是其能力的延伸。 <ul><li>一个个具体的函数或 API，让 Agent 能够与外部世界互动。例如：搜索 运行代码 等。</li><li>就像员工可用的 各种办公软件和技能，如 Excel、浏览器、电话、打印机。</li></ul></li><li>Memory (记忆)： 记录工作过程，保证任务的连贯性。 <ul><li>记录对话历史（短期）和存储专业知识库（长期）。</li><li>就像员工的 工作笔记和项目档案，避免重复劳动，让每次工作都能基于之前的经验。</li></ul></li></ul><p>如图所示 <img src="'+A+'" alt="ai_2026-03-24_162605_454.png" loading="lazy"></p>',33)])])}const b=l(r,[["render",g]]);export{h as __pageData,b as default};
